const fs = require('fs')
const path = require('path')
const { scan, derive } = require('@dotenvx/primitives')

module.exports = function file (options = {}) {
  const paths = Array.isArray(options.fk) ? options.fk : [options.fk || '.env.keys']
  const filepaths = paths.map(filepath => path.resolve(options.cwd || '.', filepath))

  return {
    async get (publicKey) {
      for (const filepath of filepaths) {
        let source
        try {
          source = await fs.promises.readFile(filepath, 'utf8')
        } catch {
          continue
        }
        const ring = matchingKey(source, publicKey)
        if (ring[publicKey]) return ring
      }
      return {}
    },
    getSync (publicKey) {
      for (const filepath of filepaths) {
        let source
        try {
          source = fs.readFileSync(filepath, 'utf8')
        } catch {
          // Match existing file-key lookup: unavailable files allow fallback.
          continue
        }
        const ring = matchingKey(source, publicKey)
        if (ring[publicKey]) return ring
      }
      return {}
    }
  }
}

function matchingKey (source, publicKey) {
  const { parsed } = scan(source)
  for (const name of Object.keys(parsed)) {
    if (!name.startsWith('DOTENV_PRIVATE_KEY')) continue
    for (const value of parsed[name]) {
      for (const privateKey of value.split(',')) {
        try {
          if (derive(privateKey) === publicKey) return { [publicKey]: privateKey }
        } catch {
          // Invalid entries must not prevent finding another valid key.
        }
      }
    }
  }
  return {}
}
